import os
from auto_config.generator.utils.logger import logger

TL = None
DEBUG = os.environ.get("TELEMETRY_DEBUG")


def _log(msg):
    if DEBUG:
        logger.info(f"[TELE] {msg}")


def _tl_register():
    global TL
    try:
        if TL is None:
            import taf.ul.telemetry
            TL = taf.ul.telemetry.telemetry_register()
    except Exception as exc:
        _log(f"Cannot register: {exc}")
    return TL


def tl_update(counter_id, counter_value, metadata):
    try:
        _log(f"Update: {counter_id} {counter_value} {metadata}")
        _tl_register()
        TL.update(counter_id, counter_value, metadata)
    except Exception as exc:
        _log(f"Cannot update: {exc}")
